-- Fixed Restaurant operations in the existing capability and receipt registries.
-- Codes do not grant themselves. No existing role/outlet assignment changes.
alter table feedx_integrations.capabilities drop constraint capabilities_action_type_check;
alter table feedx_integrations.capabilities add constraint capabilities_action_type_check check(action_type in ('view','list','read','search','filter','draft','execute','create','update','submit','complete','verify','approve','cancel','confirm','receive','return_to_draft'));

-- The navigation/action key identifies a supported resource workflow, not its shared page.
-- Inspection and Maintenance have distinct action grants; Asset Tracking remains their View owner.
update feedx_integrations.adapters set tools=tools||'[{"name":"query_restaurant_resources","description":"Explicitly granted Restaurant outlet evidence and canonical P&L"}]'::jsonb where key='factory_mesti';
notify pgrst,'reload schema';

-- Preserve the existing unique navigation/action index and make registration drift explicit.
do $$ begin
 if exists(select 1 from feedx_integrations.capabilities where workspace='Restaurant' group by navigation_module_id,action_type having count(*)>1) then raise exception 'Restaurant capability workflow/action identity is duplicated';end if;
 if exists(select 1 from feedx_integrations.factory_actions a join feedx_integrations.capabilities c on c.tool_id=a.key where c.workspace='Restaurant' and (c.navigation_module_id is null or c.action_type<>a.action or c.permission_code<>'restaurant_agent_action_'||a.key)) then raise exception 'Restaurant action capability contract does not match its executor';end if;
end $$;
